// Create a PayPal order for the browser's cart. Only sku and quantity are taken
// from the client; prices come from the server-side catalog.
app.post("/api/orders", async (req, res) => {
  try {
    const { cart } = req.body ?? {};
    if (!Array.isArray(cart) || cart.length === 0) {
      return res.status(400).json({ error: "Cart is empty." });
    }
    const lines = [];
    for (const item of cart) {
      const product = Object.hasOwn(CATALOG, item?.sku) ? CATALOG[item.sku] : null;
      const quantity = Number(item?.quantity);
      if (!product || !Number.isInteger(quantity) || quantity < 1) {
        return res.status(400).json({ error: "Invalid cart item." });
      }
      lines.push({ sku: product.sku, name: product.name, price: product.price, quantity });
    }
    const total = lines.reduce((sum, line) => sum + line.price * line.quantity, 0);
    const { jsonResponse, httpStatusCode } = await createOrder(total);
    if (jsonResponse.id) {
      orders.set(jsonResponse.id, { id: jsonResponse.id, status: "created", cart: lines, total });
    }
